const c=document.querySelector('#sky'),x=c.getContext('2d'),W=1280,H=800,$=s=>document.querySelector(s),key={};let fly=false,last=0,p,world,drag;
function reset(){p={x:0,y:0,z:3200,heading:90,pitch:0,roll:0,speed:280,score:0,landed:false};world={next:{x:900,y:-500},airport:{x:3300,y:-1050,heading:84},clouds:Array.from({length:42},()=>({x:Math.random()*8000-1000,y:Math.random()*5000-2500,s:40+Math.random()*140}))};update()}
function update(){ $('#spd').textContent=Math.round(p.speed);$('#alt').textContent=Math.round(p.z);$('#hdg').textContent=String((Math.round(p.heading)+360)%360).padStart(3,'0')+'°'}
function start(){reset();fly=true;$('#start').classList.add('off');last=performance.now();requestAnimationFrame(loop)}
function loop(t){let d=Math.min(.04,(t-last)/1000);last=t;if(fly)tick(d);draw();if(fly)requestAnimationFrame(loop)}
function tick(d){let turn=(key.a||key.arrowleft?1:0)-(key.d||key.arrowright?1:0),lift=(key.w||key.arrowup?1:0)-(key.s||key.arrowdown?1:0);if(drag){turn=(drag.x-W/2)/300;lift=(H/2-drag.y)/220}p.roll+=(turn*.7-p.roll)*d*2.2;p.pitch+=(lift*.28-p.pitch)*d*2;p.heading+=p.roll*42*d;p.speed=Math.max(140,Math.min(430,p.speed+(lift*18-p.pitch*8)*d));p.z+=p.pitch*p.speed*.9*d;p.z=Math.max(0,p.z);let r=p.heading*Math.PI/180;p.x+=Math.cos(r)*p.speed*d;p.y-=Math.sin(r)*p.speed*d;let dx=world.next.x-p.x,dy=world.next.y-p.y;if(Math.hypot(dx,dy)<150){p.score++;world.next={x:p.x+500+Math.random()*850,y:p.y-500+Math.random()*1000}}let ax=world.airport.x-p.x,ay=world.airport.y-p.y;if(Math.hypot(ax,ay)<180&&p.z<70&&p.speed<210&&Math.abs((((p.heading-world.airport.heading)+540)%360)-180)<18){p.landed=true;end('完美降落！你已安全抵达机场。')}if(p.z<=0&&!p.landed)end('着陆过于猛烈，请再试一次。');update()}
function end(msg){fly=false;$('#startText').textContent=msg+' 已完成 '+p.score+' 个导航点。';$('#begin').textContent='重新飞行';$('#start').classList.remove('off')}
function toScreen(wx,wy){let r=-p.heading*Math.PI/180,dx=wx-p.x,dy=wy-p.y;return {x:W/2+(dx*Math.cos(r)-dy*Math.sin(r))*.42,y:H*.57+(dx*Math.sin(r)+dy*Math.cos(r))*.16-p.z*.035}}
function draw(){let g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,'#3f9dcc');g.addColorStop(.58,'#b9e4f0');g.addColorStop(.59,'#74a65c');g.addColorStop(1,'#426940');x.fillStyle=g;x.fillRect(0,0,W,H);x.fillStyle='#fff8';world.clouds.forEach(q=>{let s=toScreen(q.x,q.y);if(s.y>0&&s.y<H*.62){x.beginPath();x.ellipse(s.x,s.y,q.s,q.s*.25,0,0,7);x.fill()}});let a=toScreen(world.airport.x,world.airport.y);x.save();x.translate(a.x,a.y);x.rotate(-(world.airport.heading-p.heading)*Math.PI/180);x.fillStyle='#343d45';x.fillRect(-160,-15,320,30);x.strokeStyle='#fff';x.lineWidth=3;x.setLineDash([16,14]);x.beginPath();x.moveTo(-145,0);x.lineTo(145,0);x.stroke();x.restore();let n=toScreen(world.next.x,world.next.y);x.strokeStyle='#ffe36c';x.lineWidth=4;x.beginPath();x.arc(n.x,n.y,30+Math.sin(performance.now()/300)*5,0,7);x.stroke();x.fillStyle='#ffe36c';x.font='bold 13px sans-serif';x.fillText('导航点 '+(p.score+1),n.x-30,n.y-43);drawPlane();x.fillStyle='#07121fcc';x.fillRect(W/2-92,H-118,184,90);x.strokeStyle='#fff4';x.strokeRect(W/2-92,H-118,184,90);x.save();x.translate(W/2,H-73);x.rotate(-p.roll);x.strokeStyle='#9edaff';x.lineWidth=3;x.beginPath();x.moveTo(-70,0);x.lineTo(70,0);x.moveTo(0,-38);x.lineTo(0,38);x.stroke();x.restore();x.fillStyle='#d9efff';x.font='12px sans-serif';x.fillText('姿态仪',W/2-20,H-99)}
function drawPlane(){x.save();x.translate(W/2,H*.74);x.rotate(-p.roll);x.fillStyle='#f5f7f3';x.beginPath();x.moveTo(0,-39);x.lineTo(12,14);x.lineTo(65,28);x.lineTo(61,38);x.lineTo(10,25);x.lineTo(5,48);x.lineTo(-5,48);x.lineTo(-10,25);x.lineTo(-61,38);x.lineTo(-65,28);x.lineTo(-12,14);x.closePath();x.fill();x.fillStyle='#28557b';x.beginPath();x.ellipse(0,-10,7,13,0,0,7);x.fill();x.restore()}
addEventListener('keydown',e=>{key[e.key.toLowerCase()]=true;e.preventDefault()});addEventListener('keyup',e=>key[e.key.toLowerCase()]=false);c.addEventListener('pointerdown',e=>drag={x:e.offsetX*W/c.clientWidth,y:e.offsetY*H/c.clientHeight});c.addEventListener('pointermove',e=>{if(e.buttons)drag={x:e.offsetX*W/c.clientWidth,y:e.offsetY*H/c.clientHeight}});addEventListener('pointerup',()=>drag=null);$('#begin').onclick=start;reset();draw();
